    for row_idx, row in enumerate(grid):
        new_row = list(row)  # start with copy

        # Get frame values for this row
        frame_vals = [row[c] for c in frame_cols]
        has_6 = any(v == 6 for v in frame_vals)
        has_4 = any(v == 4 for v in frame_vals)

